import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-written PTX implementing a depthwise 2D convolution with an
# asymmetric (K x 1) kernel.
#
# Structural optimization over the naive one-thread-per-output kernel:
# each CTA now cooperatively stages a reusable strip of input activations
# for a tile of output columns/rows into shared memory once, and all
# threads within the CTA reuse that data across the K height taps
# (register/shared-memory reuse instead of redundant global loads per
# output element).  Because the kernel width is always 1, the input
# column needed for a given output column (ow) does not depend on the
# tap index, so all TILE_OH outputs sharing that column can reuse the
# same cached input strip.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.3
.target sm_89
.address_size 64

.visible .entry dwconv2d_kernel(
    .param .u64 X_ptr,
    .param .u64 W_ptr,
    .param .u64 B_ptr,
    .param .u64 Y_ptr,
    .param .u32 N,
    .param .u32 C,
    .param .u32 H,
    .param .u32 Win,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 padding,
    .param .u32 dilation,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 has_bias
)
{
    .reg .pred %p<20>;
    .reg .b32  %r<80>;
    .reg .b64  %rd<30>;
    .reg .f32  %f<10>;

    // TILE_OW = 32, TILE_OH = 8, SPAN_MAX = 64 floats per column
    .shared .align 4 .b8 smem[8192];

    ld.param.u64 %rd1, [X_ptr];
    ld.param.u64 %rd2, [W_ptr];
    ld.param.u64 %rd3, [B_ptr];
    ld.param.u64 %rd4, [Y_ptr];
    ld.param.u32 %r1,  [N];
    ld.param.u32 %r2,  [C];
    ld.param.u32 %r3,  [H];
    ld.param.u32 %r4,  [Win];
    ld.param.u32 %r5,  [K];
    ld.param.u32 %r6,  [stride];
    ld.param.u32 %r7,  [padding];
    ld.param.u32 %r8,  [dilation];
    ld.param.u32 %r9,  [Hout];
    ld.param.u32 %r10, [Wout];
    ld.param.u32 %r11, [has_bias];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    // thread/block indices
    mov.u32 %r12, %tid.x;      // tidx (0..31) -> ow within tile
    mov.u32 %r13, %tid.y;      // tidy (0..7)  -> oh within tile
    mov.u32 %r14, %ctaid.x;    // ow tile idx
    mov.u32 %r15, %ctaid.y;    // oh tile idx
    mov.u32 %r16, %ctaid.z;    // n*C + c

    // c = bidz % C, n = bidz / C
    div.u32 %r17, %r16, %r2;   // n
    rem.u32 %r18, %r16, %r2;   // c

    // ow_tile_start = bidx*32 ; oh_tile_start = bidy*8
    shl.b32 %r19, %r14, 5;     // *32
    shl.b32 %r20, %r15, 3;     // *8

    add.s32 %r21, %r19, %r12;  // ow
    add.s32 %r22, %r20, %r13;  // oh

    // iw = ow*stride - padding
    mul.lo.s32 %r23, %r21, %r6;
    sub.s32 %r23, %r23, %r7;   // iw

    // ih_base = oh_tile_start*stride - padding
    mul.lo.s32 %r24, %r20, %r6;
    sub.s32 %r24, %r24, %r7;   // ih_base

    // iw valid check
    setp.lt.s32 %p1, %r23, 0;
    setp.ge.s32 %p2, %r23, %r4;
    or.pred %p3, %p1, %p2;     // p3 = iw invalid

    // span = (TILE_OH-1)*stride + (K-1)*dilation + 1
    mul.lo.s32 %r25, %r6, 7;
    sub.s32 %r26, %r5, 1;
    mul.lo.s32 %r26, %r26, %r8;
    add.s32 %r25, %r25, %r26;
    add.s32 %r25, %r25, 1;      // span

    // shared mem base address
    mov.u32 %r27, smem;
    // column base = tidx * 256 bytes (SPAN_MAX*4)
    shl.b32 %r28, %r12, 8;
    add.s32 %r28, %r27, %r28;   // column base address in shared mem

    // load loop: row = tidy; row<span; row+=8
    mov.u32 %r29, %r13;          // row = tidy

LOAD_LOOP:
    setp.ge.s32 %p4, %r29, %r25;
    @%p4 bra LOAD_DONE;

    // ih = ih_base + row
    add.s32 %r30, %r24, %r29;

    setp.lt.s32 %p5, %r30, 0;
    setp.ge.s32 %p6, %r30, %r3;
    or.pred %p7, %p5, %p6;      // ih invalid
    or.pred %p8, %p7, %p3;      // ih or iw invalid -> zero

    mov.f32 %f1, 0f00000000;

    @%p8 bra STORE_SMEM;

    // X offset = ((n*C+c)*H + ih)*Win + iw
    mad.lo.s32 %r31, %r17, %r2, %r18;
    mad.lo.s32 %r31, %r31, %r3, %r30;
    mad.lo.s32 %r31, %r31, %r4, %r23;

    mul.wide.s32 %rd10, %r31, 4;
    add.s64 %rd11, %rd1, %rd10;
    ld.global.f32 %f1, [%rd11];

STORE_SMEM:
    // address = column_base + row*4
    shl.b32 %r32, %r29, 2;
    add.s32 %r32, %r28, %r32;
    st.shared.f32 [%r32], %f1;

    add.s32 %r29, %r29, 8;
    bra.uni LOAD_LOOP;

LOAD_DONE:
    bar.sync 0;

    // check bounds oh<Hout && ow<Wout
    setp.ge.s32 %p9, %r22, %r9;
    setp.ge.s32 %p10, %r21, %r10;
    or.pred %p11, %p9, %p10;
    @%p11 bra DONE;

    mov.f32 %f2, 0f00000000;    // accumulator
    mov.u32 %r33, 0;            // kh = 0

ACC_LOOP:
    setp.ge.s32 %p12, %r33, %r5;
    @%p12 bra ACC_DONE;

    // idx = tidy*stride + kh*dilation
    mul.lo.s32 %r34, %r13, %r6;
    mul.lo.s32 %r35, %r33, %r8;
    add.s32 %r34, %r34, %r35;

    shl.b32 %r36, %r34, 2;
    add.s32 %r36, %r28, %r36;
    ld.shared.f32 %f3, [%r36];

    // W offset = c*K + kh
    mad.lo.s32 %r37, %r18, %r5, %r33;
    mul.wide.s32 %rd12, %r37, 4;
    add.s64 %rd13, %rd2, %rd12;
    ld.global.f32 %f4, [%rd13];

    fma.rn.f32 %f2, %f3, %f4, %f2;

    add.s32 %r33, %r33, 1;
    bra.uni ACC_LOOP;

ACC_DONE:

    setp.eq.s32 %p13, %r11, 0;
    @%p13 bra STORE_Y;

    mul.wide.s32 %rd14, %r18, 4;
    add.s64 %rd15, %rd3, %rd14;
    ld.global.f32 %f5, [%rd15];
    add.f32 %f2, %f2, %f5;

STORE_Y:
    mad.lo.s32 %r38, %r17, %r2, %r18;
    mad.lo.s32 %r38, %r38, %r9, %r22;
    mad.lo.s32 %r38, %r38, %r10, %r21;

    mul.wide.s32 %rd16, %r38, 4;
    add.s64 %rd17, %rd4, %rd16;
    st.global.f32 [%rd17], %f2;

DONE:
    ret;
}
"""

_KERNEL_NAME = "dwconv2d_kernel"
_ptx_module_cache = None

_TILE_OW = 32
_TILE_OH = 8


def _get_ptx_module():
    global _ptx_module_cache
    if _ptx_module_cache is None:
        _ptx_module_cache = PtxModule(PTX_SOURCE)
    return _ptx_module_cache


def validate_generated_code():
    """
    Compiles (lazily) the PTX module and verifies that the expected entry
    point exists. Raises if the module or the kernel entry cannot be found.
    """
    module = _get_ptx_module()
    fn = module.function(_KERNEL_NAME)
    if fn is None:
        raise RuntimeError(f"PTX entry '{_KERNEL_NAME}' not found in module")
    return True


class ModelNew(nn.Module):
    """
    Depthwise 2D convolution with an asymmetric kernel (kernel_size x 1),
    implemented as a hand-written, CTA-tiled PTX kernel that stages
    reusable input strips in shared memory launched via
    cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self,
                 in_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 bias: bool = False) -> None:
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(dilation, int) and dilation >= 1

        self.in_channels = int(in_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)

        C = self.in_channels
        K = self.kernel_size
        # Weight layout matches PyTorch depthwise conv: [C, 1, K, 1]
        self.weight = nn.Parameter(torch.empty(C, 1, K, 1))
        if bias:
            self.bias = nn.Parameter(torch.empty(C))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.kernel_size
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dim() == 4, "input must be [N, C, H, W]"
        x = x.contiguous().to(torch.float32)

        N, C, H, Win = x.shape
        assert C == self.in_channels

        K = self.kernel_size
        stride = self.stride
        padding = self.padding
        dilation = self.dilation

        Hout = (H + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - 1) // stride + 1  # kernel width = 1
        assert Hout > 0 and Wout > 0

        w = self.weight.contiguous().to(torch.float32).view(C, K)

        has_bias = 1 if self.bias is not None else 0
        if self.bias is not None:
            b = self.bias.contiguous().to(torch.float32)
        else:
            # dummy 1-element buffer; never dereferenced since has_bias == 0
            b = torch.zeros(1, dtype=torch.float32, device=x.device)

        y = torch.empty((N, C, Hout, Wout), dtype=torch.float32, device=x.device)

        grid_x = (Wout + _TILE_OW - 1) // _TILE_OW
        grid_y = (Hout + _TILE_OH - 1) // _TILE_OH
        grid_z = N * C
        if grid_x < 1:
            grid_x = 1
        if grid_y < 1:
            grid_y = 1
        if grid_z < 1:
            grid_z = 1

        module = _get_ptx_module()
        kernel = module.function(_KERNEL_NAME)

        stream = torch.cuda.current_stream(x.device)

        kernel.launch(
            grid=(grid_x, grid_y, grid_z),
            block=(_TILE_OW, _TILE_OH, 1),
            args=[
                u64(x.data_ptr()),
                u64(w.data_ptr()),
                u64(b.data_ptr()),
                u64(y.data_ptr()),
                i32(N),
                i32(C),
                i32(H),
                i32(Win),
                i32(K),
                i32(stride),
                i32(padding),
                i32(dilation),
                i32(Hout),
                i32(Wout),
                i32(has_bias),
            ],
            stream=stream.cuda_stream,
        )

        return y

