import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-written PTX implementing a depthwise 2D convolution with an
# asymmetric (K x 1) kernel.
#
# Structural rewrite vs. the previous "one-thread-per-output" direct kernel:
#   - CTA-level output tiling: each CTA now owns a (BLOCK_W ow-columns x
#     TILE_OH oh-rows) tile of outputs for a single (n, c) pair.
#   - Shared-memory staging of the reusable input column: since the kernel
#     width is always 1, there is no reuse across ow, but there IS heavy
#     reuse across oh (adjacent output rows read overlapping input rows for
#     the K height taps).  Each CTA cooperatively loads the required input
#     rows for its tile (per ow-column) into shared memory once, and all
#     TILE_OH threads that share that ow-column then reuse the cached rows
#     for their K-tap accumulation instead of re-reading global memory.
#   - The tiny per-channel weight vector (K taps) is also staged into shared
#     memory once per CTA instead of being re-read from global memory by
#     every thread for every tap.
# ---------------------------------------------------------------------------
