    mad.lo.s32 %r42, %r33, %r2, %r34;
    mad.lo.s32 %r42, %r42, %r3, %r41;
    mad.lo.s32 %r42, %r42, %r4, %r35;
    mul.wide.s32 %rd10, %r42, 4;
    add.s64 %rd11, %rd1, %rd10;
    ld.global.f32 %f1, [%rd11];

