class ModelNew(nn.Module):
    """
    Depthwise 2D convolution with an asymmetric kernel (kernel_size x 1),
    implemented as a hand-written PTX kernel launched via
    cutegen.ptx_runtime.PtxModule.

    Optimization: cooperative output-row tiling with shared-memory staging
    of the reusable input column per thread (each thread now computes a
    TILE_OH-sized block of output rows instead of a single output element,
    reusing input reads across the sliding K-tap window via shared memory).
    """

    def __init__(self,
                 in_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 bias: bool = False) -> None:
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(dilation, int) and dilation >= 1

        self.in_channels = int(in_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)

        C = self.in_channels
        K = self.kernel_size
        # Weight layout matches PyTorch depthwise conv: [C, 1, K, 1]
        self.weight = nn.Parameter(torch.empty(C, 1, K, 1))
        if bias:
            self.bias = nn.Parameter(torch.empty(C))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.kernel_size
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dim() == 4, "input must be [N, C, H, W]"
        x = x.contiguous().to(torch.float32)

        N, C, H, Win = x.shape
        assert C == self.in_channels

        K = self.kernel_size
        stride = self.stride
        padding = self.padding
        dilation = self.dilation

        Hout = (H + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - 1) // stride + 1  # kernel width = 1
        assert Hout > 0 and Wout > 0

        w = self.weight.contiguous().to(torch.float32).view(C, K)

        has_bias = 1 if self.bias is not None else 0
        if self.bias is not None:
            b = self.bias.contiguous().to(torch.float32)
        else:
            # dummy 1-element buffer; never dereferenced since has_bias == 0
            b = torch.zeros(1, dtype=torch.float32, device=x.device)

        y = torch.empty((N, C, Hout, Wout), dtype=torch.float32, device=x.device)

        # Compressed grid: each thread owns one (n, c, ow) column and a
        # TILE_OH-sized block of output rows (matches PTX-side constant).
        hout_tiles = (Hout + _TILE_OH - 1) // _TILE_OH
        total = N * C * hout_tiles * Wout

        block_x = _BLOCK_X
        grid_x = (total + block_x - 1) // block_x
        if grid_x < 1:
            grid_x = 1

        module = _get_ptx_module()
        kernel = module.function(_KERNEL_NAME)
        stream = torch.cuda.current_stream(x.device)
        kernel_args = [
            u64(x.data_ptr()),
            u64(w.data_ptr()),
            u64(b.data_ptr()),
            u64(y.data_ptr()),
            i32(N),
            i32(C),
            i32(H),
            i32(Win),
            i32(K),
            i32(stride),
            i32(padding),
            i32(dilation),
            i32(Hout),
            i32(Wout),
            i32(has_bias),
        ]
        module.launch(
            kernel,
            (grid_x, 1, 1),
            (block_x, 1, 1),
            kernel_args,
            stream=stream,
        )

        return y

